dleplugin.phpinstall:
if (class_exists('DLEUrl')) {
    $rules = ['forum_main', 'forum_new_topic', 'forum_new_topic_cat', 'forum_search', 'forum_edit', 'forum_profile', 'forum_topic_page', 'forum_topic_slash', 'forum_topic', 'forum_topic_alt', 'forum_cat_page', 'forum_cat', 'forum_reply', 'forum_reply_id'];
    foreach($rules as $r) { DLEUrl::DeleteRule('custom.' . $r); }

    DLEUrl::AddRule('forum_main',      '/forum/',                    '/index.php?do=forum');
    DLEUrl::AddRule('forum_new_topic', '/forum/new-topic/',          '/index.php?do=forum&action=new_topic');
    DLEUrl::AddRule('forum_new_topic_cat', '/forum/new-topic/{category:[a-zA-Z0-9_-]+}/', '/index.php?do=forum&action=new_topic&cat={category}');
    DLEUrl::AddRule('forum_reply',     '/forum/reply/',              '/index.php?do=forum&action=reply');
    DLEUrl::AddRule('forum_reply_id',  '/forum/reply/{newsid}/',     '/index.php?do=forum&action=reply&topic_id={newsid}');
    DLEUrl::AddRule('forum_search',    '/forum/search/',             '/index.php?do=forum&action=search');
    DLEUrl::AddRule('forum_edit',      '/forum/edit/{newsid}/',      '/index.php?do=forum&action=edit&id={newsid}');
    DLEUrl::AddRule('forum_profile',   '/forum/user/{user}/',        '/index.php?do=forum&action=profile&user={user}');
    DLEUrl::AddRule('forum_topic_page','/forum/topic/{newsid}-{news_name}/page/{cstart}/', '/index.php?do=forum&action=topic&id={newsid}&page={cstart}');
    DLEUrl::AddRule('forum_topic_slash','/forum/topic/{newsid}-{news_name}/', '/index.php?do=forum&action=topic&id={newsid}');
    DLEUrl::AddRule('forum_topic',     '/forum/topic/{newsid}-{news_name}.html',         '/index.php?do=forum&action=topic&id={newsid}');
    DLEUrl::AddRule('forum_topic_alt', '/forum/{news_name:[a-zA-Z0-9_-]+}.html',         '/index.php?do=forum&action=topic&alt_name={news_name}');
    DLEUrl::AddRule('forum_cat_page',  '/forum/{category:[a-zA-Z0-9_-]+}/page/{cstart}/', '/index.php?do=forum&action=category&cat={category}&page={cstart}');
    DLEUrl::AddRule('forum_cat',       '/forum/{category:[a-zA-Z0-9_-]+}/',             '/index.php?do=forum&action=category&cat={category}');

    if (is_array(DLEUrl::$rules)) {
        $custom_rules = []; $other_rules = [];
        foreach(DLEUrl::$rules as $k => $v) {
            if (strpos($k, 'custom.forum_') === 0) { $custom_rules[$k] = $v; } else { $other_rules[$k] = $v; }
        }
        DLEUrl::$rules = array_merge($custom_rules, $other_rules);
        DLEUrl::SaveRules(DLEUrl::$rules);
    }
}

